# Table 1 of the paper: the ten largest and ten smallest changes in exposure from stage 1 to stage 4 among the harmonized
# occupations, with the stage 1 to 3 change, 2019 employment, the 2019 real hourly wage, the 2019 share with a bachelor's
# degree or more, and reported AI adoption. Inputs (data/pipeline/): occ2010_measures.dta (scores and adoption),
# occ2010_quarter_panel_v2.dta (2019 employment, wages, education), occ2010_labels.csv (IPUMS OCC2010 titles).
# Employment is the quarterly sum of monthly CPS weights divided by three (a monthly average), averaged over the four quarters of
# 2019; the wage is exp of the 2019 mean of the occupation's mean log real hourly earnings (log_hrearn_nt, outgoing rotation
# groups, January 2020 dollars); the degree share adds the top two education quartile shares (prop_educ_q3 + prop_educ_q4).
# Adoption is the share using generative AI at work in the Real-Time Population Survey, missing where the occupation is not covered.
# Run from anywhere: python3 code/tables/tab2-3-top-bottom.py   (writes output/tables/tab2-3-top-bottom.tex)
import sys as _sys, pathlib as _pl; _sys.path.insert(0, str(_pl.Path(__file__).resolve().parents[1])); from paths import *   # repository-relative paths (code/paths.py)
import numpy as np, pandas as pd
m = pd.read_stata(PIPELINE / "occ2010_measures.dta", convert_categoricals=False)
p = pd.read_stata(PIPELINE / "occ2010_quarter_panel_v2.dta", convert_categoricals=False)
lab = pd.read_csv(PIPELINE / "occ2010_labels.csv").set_index("occ2010").title
y = p[p.qdate.dt.year == 2019].groupby("occ2010").agg(emp=("emp", "mean"), lw=("log_hrearn_nt", "mean"), q3=("prop_educ_q3", "mean"), q4=("prop_educ_q4", "mean"))
d = m.dropna(subset=["d_ens_s4_s1"]).merge(y, on="occ2010", how="left").sort_values("d_ens_s4_s1", ascending=False)
top, bottom = d.head(10), d.tail(10).sort_values("d_ens_s4_s1")
def emp(x): return f"{x / 3e6:.1f}M" if x / 3 >= 1e6 else f"{x / 3e3:.0f}k"
def pct(x): return "--" if pd.isna(x) else f"{100 * x:.0f}\\%"
def row(r): return f"{lab[r.occ2010].capitalize()} & {r.d_ens_s4_s1:.1f} & {r.d_ens_s3_s1:.1f} & {emp(r.emp)} & \\${np.exp(r.lw):.0f} & {pct(r.q3 + r.q4)} & {pct(r.rps_adoption)} \\\\"
L = ["% Table 1: the ten largest and ten smallest changes in exposure from stage 1 to stage 4, from the harmonized occupation scores (occ2010_measures.dta).",
     "% Generated by code/tables/tab2-3-top-bottom.py. Do not edit by hand.",
     "\\begin{table}[htbp]", "\\centering", "\\begin{threeparttable}", "\\caption{The ten largest and ten smallest exposure changes}", "\\label{tab:topbottom}",
     "\\footnotesize\\setlength{\\tabcolsep}{4pt}", "\\begin{spacing}{1}", "\\begin{tabular}{@{}p{6.0cm}rrrrrr@{}}", "\\toprule",
     "Occupation & $\\Delta$S4$-$S1 & $\\Delta$S3$-$S1 & Employment & Real wage & BA+ & AI adoption \\\\", "\\midrule",
     "\\multicolumn{7}{@{}l}{\\emph{Ten largest changes}} \\\\"] + [row(r) for r in top.itertuples()] + ["\\addlinespace",
     "\\multicolumn{7}{@{}l}{\\emph{Ten smallest changes}} \\\\"] + [row(r) for r in bottom.itertuples()] + ["\\bottomrule", "\\end{tabular}", "\\end{spacing}",
     "\\begin{tablenotes}\\notesize",
     "\\item Notes: Occupations ranked by the change in exposure from stage 1 to stage 4, with the change from stage 1 to stage 3 alongside. Employment and the share with a bachelor's degree or more are 2019 values; the real hourly wage is in January 2020 dollars; AI adoption is from the Real-Time Population Survey waves of 2025 to 2026 where the occupation is covered.",
     "\\end{tablenotes}", "\\end{threeparttable}", "\\end{table}"]
(TABLES / "tab2-3-top-bottom.tex").write_text("\n".join(L) + "\n"); print("wrote output/tables/tab2-3-top-bottom.tex")
